import{_ as s,C as n,c as a,o as r,a3 as t,G as i}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Profit and loss","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/reporting/profit-and-loss.md","filePath":"master/finance/reporting/profit-and-loss.md","lastUpdated":1791902625000}'),l={name:"master/finance/reporting/profit-and-loss.md"};function h(d,e,p,u,c,g){const o=n("ImagePopup");return r(),a("div",null,[e[0]||(e[0]=t('<h1 id="profit-and-loss" tabindex="-1">Profit and loss <a class="header-anchor" href="#profit-and-loss" aria-label="Permalink to &quot;Profit and loss&quot;">​</a></h1><p>The profit and loss report compares what you earned with what you spent in a period. The result is your net profit. Use it every month to see if the business makes money.</p><blockquote><p><strong>In simple words:</strong> Revenue minus expenses equals profit. This report adds both up for the dates you choose.</p></blockquote><p>It is in the Accounting app only: <code>Accounting → Reporting → Profit &amp; Loss</code>.</p><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2>',5)),i(o,{src:"/images1/finance/profit_and_loss.png",alt:"Profit & Loss with Date Range Last Quarter (01/07/2026 - 30/09/2026) showing Revenue, Expenses and Net Profit"}),e[1]||(e[1]=t('<ul><li><strong><em>Date Range:</em></strong> The period to measure. Only entries dated inside the range count.</li><li><strong><em>Journals:</em></strong> Limit the report to chosen journals.</li></ul><p>The default range is the current month. The sample data is dated July 2026, so choose <strong>Last Quarter</strong> in the <strong>Date Range</strong> (01/07/2026 - 30/09/2026). With the default range the report says &quot;No revenue accounts with transactions in this period&quot; and the net result is 0.00.</p><h2 id="how-to-read-it" tabindex="-1">How to read it <a class="header-anchor" href="#how-to-read-it" aria-label="Permalink to &quot;How to read it&quot;">​</a></h2><p>The report has two columns: <strong>Account</strong> and <strong>Amount</strong>.</p><ul><li><strong>REVENUE:</strong> Income accounts, such as <strong>400000 Product Sales</strong>. The block ends with a total.</li><li><strong>EXPENSES:</strong> Expense accounts, such as <strong>600000 Expenses</strong>. The block ends with a total.</li><li><strong>Net Profit</strong> or <strong>Net Loss:</strong> Revenue total minus expenses total. The label changes to <strong>Net Loss</strong> when expenses are higher.</li></ul><p>Example for July 2026, taken from the posted entries:</p><table tabindex="0"><thead><tr><th>Block</th><th>Account</th><th>Amount</th></tr></thead><tbody><tr><td>Revenue</td><td>400000 Product Sales</td><td>1,825.00</td></tr><tr><td>Expenses</td><td>600000 Expenses</td><td>29,600.00</td></tr><tr><td></td><td>Net Loss</td><td>27,775.00</td></tr></tbody></table><p>Revenue of $1,825.00 comes from invoices INV/2026/1 and INV/2026/2 before tax ($1,050.00 and $775.00). Expenses of $29,600.00 come from bill BILL/2026/4 before tax.</p><p>The red <strong>Net Loss</strong> line means a loss. This is the same number as the <strong>Current Year Unallocated Earnings</strong> on the <a href="./balance-sheet.html">Balance sheet</a>.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Click <strong>Export to Excel</strong> or <strong>Export to PDF</strong> to download the report.</p><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>Why is the tax not in the report?</strong> Tax is not revenue or expense. It sits in the tax accounts on the balance sheet.</p><p><strong>Why does the paid bill still count?</strong> The report counts the cost when you post the bill, not when you pay it.</p><p><strong>Why is my report all zero?</strong> No posted entries fall in the range. Change the <strong>Date Range</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./balance-sheet.html">Balance sheet</a></li><li><a href="./general-ledger.html">General ledger</a></li><li><a href="./">Reporting overview</a></li></ul>',17))])}const _=s(l,[["render",h]]);export{f as __pageData,_ as default};
